## solutions

#### iterative

```cpp
Node* mergeLists(Node* head1, Node* head2) {
  Node dummyHead(0);
  Node* tail = &dummyHead;

  Node* current1 = head1;
  Node* current2 = head2;
  while (current1 != nullptr and current2 != nullptr) {
    if (current1->val < current2->val) {
      tail->next = current1;
      current1 = current1->next;
    } else {
      tail->next = current2;
      current2 = current2->next;
    }
    tail = tail->next;
  }

  if (current1 != nullptr) {
    tail->next = current1;
  }
  if (current2 != nullptr) {
    tail->next = current2;
  }

  return dummyHead.next;
}
```

- n = length of list 1
- m = length of list 2
- Time: O(min(n, m))
- Space: O(1)

#### recursive

```cpp
Node* mergeLists(Node* head1, Node* head2) {
  if (head1 == nullptr) {
    return head2;
  }

  if (head2 == nullptr) {
    return head1;
  }

  if (head1->val < head2->val) {
    head1->next = mergeLists(head1->next, head2);
    return head1;
  } else {
    head2->next = mergeLists(head1, head2->next);
    return head2;
  }
}
```

- n = length of list 1
- m = length of list 2
- Time: O(min(n, m))
- Space: O(min(n, m))
